102	export class CoreToolScheduler {
103	  // Static WeakMap to track which MessageBus instances already have a handler subscribed
104	  // This prevents duplicate subscriptions when multiple CoreToolScheduler instances are created
105	  private static subscribedMessageBuses = new WeakMap<
106	    MessageBus,
107	    (request: ToolConfirmationRequest) => void
108	  >();
109	
110	  private toolCalls: ToolCall[] = [];
111	  private outputUpdateHandler?: OutputUpdateHandler;
112	  private onAllToolCallsComplete?: AllToolCallsCompleteHandler;
113	  private onToolCallsUpdate?: ToolCallsUpdateHandler;
114	  private getPreferredEditor: () => EditorType | undefined;
115	  private config: Config;
116	  private isFinalizingToolCalls = false;
117	  private isScheduling = false;
118	  private isCancelling = false;
119	  private requestQueue: Array<{
120	    request: ToolCallRequestInfo | ToolCallRequestInfo[];
121	    signal: AbortSignal;
122	    resolve: () => void;
123	    reject: (reason?: Error) => void;
124	  }> = [];
125	  private toolCallQueue: ToolCall[] = [];
126	  private completedToolCallsForBatch: CompletedToolCall[] = [];
127	  private toolExecutor: ToolExecutor;
128	  private toolModifier: ToolModificationHandler;
129	
130	  constructor(options: CoreToolSchedulerOptions) {
131	    this.config = options.config;
132	    this.outputUpdateHandler = options.outputUpdateHandler;
133	    this.onAllToolCallsComplete = options.onAllToolCallsComplete;
134	    this.onToolCallsUpdate = options.onToolCallsUpdate;
135	    this.getPreferredEditor = options.getPreferredEditor;
136	    this.toolExecutor = new ToolExecutor(this.config);
137	    this.toolModifier = new ToolModificationHandler();
138	
139	    // Subscribe to message bus for ASK_USER policy decisions
140	    // Use a static WeakMap to ensure we only subscribe ONCE per MessageBus instance
